def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp_defects = 0
    my_defects = 0
    first_opp_d = -1
    for i in range(n):
        me, opp = history[i]
        if opp == 'D':
            opp_defects += 1
            if first_opp_d == -1:
                first_opp_d = i
        if me == 'D':
            my_defects += 1
    last_my, last_opp = history[-1]

    if n == 99:
        return 'D'

    if n >= 1 and opp_defects == n:
        return 'D'
    if n >= 5 and opp_defects >= 3 and opp_defects * 2 >= n:
        return 'D'
    if n >= 10:
        recent_opp_d = 0
        for i in range(n-10, n):
            if history[i][1] == 'D':
                recent_opp_d += 1
        if recent_opp_d >= 7:
            return 'D'

    if first_opp_d > 80:
        return 'D'

    if last_opp == 'D':
        if last_my == 'D':
            return 'C'
        else:
            recent_my_defect = False
            if n >= 2 and history[-2][0] == 'D':
                recent_my_defect = True
            if n >= 3 and history[-3][0] == 'D':
                recent_my_defect = True
            if recent_my_defect and opp_defects <= 2:
                return 'C'
            return 'D'
    else:
        if last_my == 'D':
            return 'C'
        return 'C'
